  Lemma gbb_loop : forall (l : list Z) (c : Z) (cur best : Z) (x15 x16 x17 x5 : word),
    u64arr asegs m cur (wlist (c :: l)) -> cur + 8 * (1 + zlen l) = pe -> 0 <= cur -> pe <= aceil ->
